const signals = $input.all().map((item) => item.json);
const uniqueDomains = [...new Set(
  signals
    .map((s) => String(s.companyDomain || (Array.isArray(s.mentionedDomains) ? s.mentionedDomains[0] : '') || '').trim().toLowerCase())
    .filter(Boolean)
)];
if (uniqueDomains.length === 0) return [];
return [{ json: { domains: uniqueDomains } }];

const enrichedByDomain = new Map();
for (const item of $input.all()) {
  const d = String(item.json.domain || item.json.inputDomain || '').trim().toLowerCase();
  if (d) enrichedByDomain.set(d, item.json);
}

const signalItems = $('2. Keep Brand-New Buying Triggers').all();
return signalItems.map((sigItem) => {
  const s = sigItem.json;
  const dom = String(s.companyDomain || (Array.isArray(s.mentionedDomains) ? s.mentionedDomains[0] : '') || '').trim().toLowerCase();
  const enr = enrichedByDomain.get(dom) || {};
  const techStack = Array.isArray(enr.techStackNames) ? enr.techStackNames.slice(0, 8).join(', ') : '';
  const slackAlert = [
    `*[${String(s.primaryTrigger || 'signal').toUpperCase()}] ${s.matchedCompany || dom || 'Account'}*`,
    `Headline: ${s.title || ''}`,
    `Source: ${s.publisherName || 'News'} (${s.publishedAt ? String(s.publishedAt).slice(0, 10) : ''}) | ${s.url || s.googleNewsUrl || ''}`,
    `Contact: ${enr.bestEmail || 'N/A'} | LinkedIn: ${enr.linkedinUrl || 'N/A'} | Provider: ${enr.emailProvider || 'N/A'}`,
    techStack ? `Tech Stack: ${techStack}` : null,
    s.icebreakerSnippet ? `Icebreaker: ${s.icebreakerSnippet}` : null
  ].filter(Boolean).join('\n');

  return {
    json: {
      publishedAt: s.publishedAt || '',
      company: s.matchedCompany || '',
      domain: dom,
      primaryTrigger: s.primaryTrigger || '',
      signalConfidence: s.signalConfidence ?? '',
      headline: s.title || '',
      publisher: s.publisherName || '',
      realUrl: s.url || s.googleNewsUrl || '',
      bestEmail: enr.bestEmail || '',
      linkedinUrl: enr.linkedinUrl || '',
      emailProvider: enr.emailProvider || '',
      techStack,
      impressumDirector: enr.impressumManagingDirector || '',
      icebreakerSnippet: s.icebreakerSnippet || '',
      slackAlert
    }
  };
});
